const kit=[['😊','Happy','Faces','good vibes'],['😂','Laughing','Faces','uncontrollable laughter'],['🥹','Touched','Faces','tender feelings'],['😎','Cool','Faces','effortless confidence'],['😭','Crying','Faces','big feelings'],['😴','Sleepy','Faces','rest mode'],['😡','Angry','Faces','pure frustration'],['🤔','Thinking','Faces','deep thoughts'],['🥳','Party','Faces','celebration'],['😇','Innocent','Faces','sweet intentions'],['🤯','Mind blown','Faces','total amazement'],['🫠','Melting','Faces','barely holding it together'],['❤️','Heart','Feelings','love'],['🔥','Fire','Elements','intensity'],['✨','Sparkles','Elements','a little magic'],['🌈','Rainbow','Elements','hope'],['💔','Heartbreak','Feelings','heartache'],['💯','Hundred','Feelings','giving it your all'],['💤','Sleep','Feelings','a well-earned break'],['💋','Kiss','Feelings','affection'],['❄️','Snowflake','Elements','chill energy'],['⚡','Lightning','Elements','a burst of energy'],['🌧️','Rain','Elements','a gloomy day'],['🌸','Blossom','Elements','a fresh start'],['👻','Ghost','Things','a playful scare'],['👑','Crown','Things','royal treatment'],['☕','Coffee','Things','a caffeine boost'],['🎉','Confetti','Things','a reason to celebrate'],['🌙','Moon','Elements','late-night vibes'],['🍕','Pizza','Things','comfort food'],['🦋','Butterfly','Things','butterflies inside'],['🎧','Headphones','Things','your own soundtrack']].map(([emoji,name,category,meaning])=>({emoji,name,category,meaning}));
const existingEmoji=new Set(kit.map(item=>item.emoji));for(const item of MischiefCatalog.items){if(!existingEmoji.has(item.emoji)){kit.push(item);existingEmoji.add(item.emoji);}}
let emojiPage=0,emojiQuery='';const pageSize=64;
const special={'0,13':['On a happy streak',"For when you're feeling good and absolutely on fire."],'12,13':['Love, turned up',"For a crush that just won't cool down."],'4,14':['Dramatically okay','A little emotional. Still sparkling.'],'5,26':['Running on coffee','When your body says nap and your calendar says no.'],'3,20':['Professionally unbothered','Ice-cold composure. Nothing can touch you.']};
let selected=[0,13],active=0,category='All',current=[0,13],currentMeaning=null;
const $=s=>document.querySelector(s);const key=(a,b)=>[a,b].sort((x,y)=>x-y).join(',');
function describe(...ids){const m=MischiefMeaning(ids.map(id=>kit[id]));return [m.title,m.description];}
function renderSlots(){const slots=$('.slots');slots.replaceChildren();selected.forEach((id,i)=>{const wrap=document.createElement('div');wrap.className='slot-wrap';const el=document.createElement('button');el.className='slot'+(i===active?' active':'');el.setAttribute('aria-label','Change ingredient '+(i+1)+': '+kit[id].name);el.setAttribute('aria-pressed',i===active);el.innerHTML='<span class="slot-num">0'+(i+1)+'</span><span class="slot-emoji">'+kit[id].emoji+'</span><span class="slot-name">'+kit[id].name+'</span>';el.onclick=()=>{active=i;renderSlots()};wrap.append(el);if(selected.length>2){const remove=document.createElement('button');remove.className='remove-slot';remove.textContent='×';remove.setAttribute('aria-label','Remove ingredient '+(i+1));remove.onclick=()=>{selected.splice(i,1);active=Math.min(active,selected.length-1);renderSlots();};wrap.append(remove)}slots.append(wrap)});if(selected.length<4){const add=document.createElement('button');add.className='add-slot';add.innerHTML='<span>+</span>Add emoji';add.onclick=()=>{selected.push(selected.length===2?12:14);active=selected.length-1;renderSlots();};slots.append(add)}$('#pickHint').textContent='Pick ingredient '+(active+1);renderGrid();}
function renderGrid(){const grid=$('#emojiGrid');grid.replaceChildren();const entries=kit.map((item,id)=>({item,id})).filter(({item})=>(category==='All'||item.category===category)&&(!emojiQuery||(item.name+' '+item.emoji+' '+(item.subgroup||'')).toLowerCase().includes(emojiQuery)));const total=Math.max(1,Math.ceil(entries.length/pageSize));emojiPage=Math.min(emojiPage,total-1);entries.slice(emojiPage*pageSize,(emojiPage+1)*pageSize).forEach(({item,id})=>{const button=document.createElement('button');button.className='emoji-button'+(selected.includes(id)?' picked':'');const glyph=document.createElement('span');glyph.className='kit-glyph';glyph.textContent=item.emoji;glyph.style.animationDelay=(-id*.13)+'s';button.append(glyph);button.title=item.name;button.setAttribute('aria-label',item.name);button.onclick=()=>{selected[active]=id;active=(active+1)%selected.length;renderSlots();$('#mix .mix-label').textContent='Mix these emojis';};grid.append(button);});$('#catalogCount').textContent=entries.length?(emojiPage*pageSize+1)+'–'+Math.min((emojiPage+1)*pageSize,entries.length)+' of '+entries.length:'No matching emojis';$('#prevPage').disabled=emojiPage===0;$('#nextPage').disabled=emojiPage>=total-1;if(!entries.length){const empty=document.createElement('p');empty.className='empty-kit';empty.textContent='Try another name or category.';grid.append(empty);}}
['All','Faces','People','Animals','Food','Travel','Activities','Things','Feelings','Elements','Symbols','Flags','Components'].forEach(label=>{const button=document.createElement('button');button.className='category'+(label==='All'?' selected':'');button.textContent=label;button.setAttribute('aria-pressed',label==='All');button.onclick=()=>{category=label;emojiPage=0;document.querySelectorAll('.category').forEach(el=>{el.classList.toggle('selected',el===button);el.setAttribute('aria-pressed',el===button)});renderGrid();};$('#categories').append(button)});
$('#emojiSearch').oninput=()=>{emojiQuery=$('#emojiSearch').value.trim().toLowerCase();emojiPage=0;renderGrid();};$('#prevPage').onclick=()=>{emojiPage=Math.max(0,emojiPage-1);renderGrid();};$('#nextPage').onclick=()=>{emojiPage++;renderGrid();};
function mix(){current=[...selected];MischiefDraft.save({emojis:current.map(id=>kit[id].emoji)});currentMeaning=MischiefMeaning(current.map(id=>kit[id]),$('#intention').value,$('#personalMeaning').value);const name=currentMeaning.title,meaning=currentMeaning.description;$('#meaningTraits').textContent=currentMeaning.traits.join(' · ');draw($('#preview'),...current);$('#preview').setAttribute('aria-label',`${name}: ${current.map(id=>kit[id].name).join(", ")} sticker`);$('#formula').textContent=current.map(id=>kit[id].emoji).join(' + ');$('#resultName').textContent=name;$('#meaning').textContent=meaning;$('#mix .mix-label').textContent='Make mischief';$('#preview').classList.remove('pop');void $('#preview').offsetWidth;$('#preview').classList.add('pop');window.dispatchEvent(new Event('mischief:mix'));}
$('#mix').onclick=mix;$('#random').onclick=()=>{selected=selected.map(()=>Math.floor(Math.random()*kit.length));renderSlots();mix()};
$('#download').onclick=()=>{exportCanvas().toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='mischief-'+describe(...current)[0].toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.png';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');};
[[7,25],[0,20],[12,13],[0,13,12,14]].forEach(pair=>{const button=document.createElement('button');button.className='recipe';const canvas=document.createElement('canvas');canvas.width=canvas.height=512;canvas.setAttribute('aria-hidden','true');draw(canvas,...pair);const text=document.createElement('span');const name=document.createElement('strong');name.textContent=describe(...pair)[0];const formula=document.createElement('small');formula.textContent=pair.map(id=>kit[id].emoji).join(' + ');text.append(name,formula);const arrow=document.createElement('span');arrow.className='recipe-arrow';arrow.textContent='↗';button.append(canvas,text,arrow);button.onclick=()=>{selected=[...pair];renderSlots();mix();};$('#recipeGrid').append(button)});const savedEmojis=MischiefDraft.read().emojis;if(savedEmojis){const restored=savedEmojis.map(emoji=>kit.findIndex(item=>item.emoji===emoji));if(restored.every(id=>id>=0))selected=restored;}renderSlots();mix();

function draw(canvas,...ids){MischiefComposition.draw(canvas,ids.map(id=>kit[id]));}
function exportCanvas(){const canvas=document.createElement('canvas');canvas.width=canvas.height=1024;draw(canvas,...current);return canvas;}
const getBlob=()=>new Promise(resolve=>exportCanvas().toBlob(resolve,'image/png'));
$('#copy').onclick=async()=>{try{if(!navigator.clipboard?.write||!window.ClipboardItem)throw Error();await navigator.clipboard.write([new ClipboardItem({'image/png':getBlob()})]);$('#actionStatus').textContent='Copied! Paste into an app that accepts images.';}catch{$('#actionStatus').textContent='Image copying is unavailable here. Download the sticker instead.';}};
$('#share').onclick=async()=>{try{const file=new File([await getBlob()],'mischief-sticker.png',{type:'image/png'});if(!navigator.canShare?.({files:[file]})){$('#actionStatus').textContent='File sharing is unavailable here. Download and attach your sticker.';return;}await navigator.share({files:[file],title:describe(...current)[0]});}catch(error){if(error.name!=='AbortError')$('#actionStatus').textContent='Could not share. Try downloading your sticker.';}};
let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else $('#installHelp').showModal();};$('#closeHelp').onclick=()=>$('#installHelp').close();window.addEventListener('appinstalled',()=>{$('#install').textContent='App installed ✓';});
if('serviceWorker' in navigator&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname)){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(reg=>{reg.update().catch(()=>{});const offer=()=>{if(!reg.waiting||document.getElementById('applyUpdate'))return;const button=document.createElement('button');button.id='applyUpdate';button.className='install';button.textContent='Update app ↻';button.onclick=()=>{navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});reg.waiting?.postMessage({type:'ACTIVATE_UPDATE'});};document.querySelector('header').append(button);};offer();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',offer);});}).catch(()=>{}));}

$('#intention').onchange=()=>mix();$('#personalMeaning').onchange=()=>mix();
window.MischiefExport=()=>({dataUrl:exportCanvas().toDataURL('image/png'),mimeType:'image/png',width:1024,height:1024,ingredients:current.map(id=>({...kit[id]})),meaning:{...currentMeaning},alt:currentMeaning.alt});
